SELECT i.order_item_id,o.order_id,c.category_id,c.c_name AS category_name,(i.qty::DECIMAL(18,0)*i.unit_price)::DECIMAL(38,2) AS line_revenue FROM orders o JOIN order_items i USING(order_id) JOIN products p USING(product_id) JOIN categories c USING(category_id) WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00' ORDER BY i.order_item_id;
